import{_ as d,o as e,c as a,a8 as r}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"119 大型 Vue 3 双端项目实战","description":"","frontmatter":{"title":"119 大型 Vue 3 双端项目实战"},"headers":[],"relativePath":"119-vue3-dual-end-project.md","filePath":"119-vue3-dual-end-project.md","lastUpdated":1793706365000}'),o={name:"119-vue3-dual-end-project.md"};function l(h,t,i,n,s,c){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="第一百一十九部分-·-大型-vue-3-双端项目实战——从需求到上线" tabindex="-1">第一百一十九部分 · 大型 Vue 3 双端项目实战——从需求到上线 <a class="header-anchor" href="#第一百一十九部分-·-大型-vue-3-双端项目实战——从需求到上线" aria-label="Permalink to &quot;第一百一十九部分 · 大型 Vue 3 双端项目实战——从需求到上线&quot;">​</a></h1><blockquote><p>🧭 <a href="./README">返回总目录</a>｜上一篇：<a href="./118-webrtc-client">第一百一十八部分 · WebRTC 客户端实战</a>｜关联章节：<a href="./113-vue3-multi-end">第一百一十三部分 · Vue 3 单仓多端工程</a> · <a href="./114-vue-router-deep">第一百一十四部分 · Vue Router 深度</a> · <a href="./115-overseas-engineering">第一百一十五部分 · 海外化工程</a> · <a href="./116-im-weak-network">第一百一十六部分 · IM 弱网与高并发治理</a> · <a href="./59-monitoring-observability">第五十九部分 · 监控与可观测性</a></p></blockquote><h2 id="本部分内容" tabindex="-1">本部分内容 <a class="header-anchor" href="#本部分内容" aria-label="Permalink to &quot;本部分内容&quot;">​</a></h2><p>前面各册拆开讲了多端目录、路由、海外化、IM、埋点与监控；这一册把它们装进一个能交付的项目：面向海外市场的 Vue 3 双端商城（PC Web + H5/PWA）。重点回答四个问题：需求怎么切、代码放哪里、双端差异怎么收口、上线凭什么敢发。四个示例覆盖脚手架生成、领域模型与 API 层、发布门禁、指标看板，均可实跑。</p><hr><h2 id="_119-1-需求拆解与范围" tabindex="-1">119.1 需求拆解与范围 <a class="header-anchor" href="#_119-1-需求拆解与范围" aria-label="Permalink to &quot;119.1 需求拆解与范围&quot;">​</a></h2><h3 id="概念解析" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>双端项目的第一个误区是「功能对等」：把 PC 的功能清单原样复制到 H5，再按 1.5 倍工时报价。真实约束是<strong>同一业务目标、两种使用场景</strong>——PC 做深度操作，H5 承接投放流量与即时决策。</p><p>拆解要产出三样东西：<strong>范围矩阵</strong>（行是模块，列是端、优先级、验收口径、依赖，没有验收口径不算拆完）、<strong>优先级</strong>（P0 缺了上不了线，P1 上线后两周补齐，P2 明确不做）、<strong>范围冻结线</strong>（T-10 个工作日冻结 P0，变更走变更单并评估双端 UI 成本）。</p><p>以海外家居 DTC「Loom &amp; Oak」（PC 商城 + 投放落地 H5）为例：</p><table tabindex="0"><thead><tr><th>模块</th><th>PC Web</th><th>H5 / PWA</th><th>优先级</th><th>验收口径</th></tr></thead><tbody><tr><td>登录 / 账户</td><td>全量，含设备管理</td><td>短信 + 第三方登录</td><td>P0</td><td>成功率 ≥ 99.5%，refresh 失败自动回登录</td></tr><tr><td>列表 / 详情</td><td>筛选、对比、多图</td><td>单列信息流、分享深链</td><td>P0</td><td>首屏 LCP P75 ≤ 2.5s，深链参数不丢</td></tr><tr><td>购物车 / 结账</td><td>多步、地址簿、发票</td><td>单页、Apple/Google Pay</td><td>P0</td><td>下单成功率 ≥ 98%，回跳可恢复</td></tr><tr><td>订单 / 售后</td><td>批量操作、导出</td><td>仅退款申请</td><td>P1</td><td>状态机无非法迁移</td></tr><tr><td>IM 客服入口</td><td>独立工作台入口</td><td>悬浮入口、半屏会话</td><td>P1</td><td>断线可重连，离线消息不丢</td></tr></tbody></table><p>反例：某团队把「H5 也要商品对比」写进 P0，首屏多加载 180KB 组件，LCP 从 2.1s 涨到 3.6s，投放转化跌了 12%。</p><h3 id="应用实践" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>每个 P0 配可量化验收：不是「支持支付」，而是「3DS 完成率 ≥ 98%，失败可重试且不重复扣款」。</li><li>拆解时标出服务端与第三方依赖（支付、分享），它们排期最不可控。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 范围矩阵与 P2「为什么不做」进项目 README，每周更新。</li><li>⚠️ 不要用复用率倒推需求：先定体验，再定哪些代码共享。</li></ul><hr><h2 id="_119-2-架构分层与目录" tabindex="-1">119.2 架构分层与目录 <a class="header-anchor" href="#_119-2-架构分层与目录" aria-label="Permalink to &quot;119.2 架构分层与目录&quot;">​</a></h2><h3 id="概念解析-1" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-1" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>目录按<strong>依赖方向</strong>切，不按页面切：页面会重组，依赖方向不会。核心约束只有一条：<strong>业务规则只住 <code>core</code>，端差异只住 <code>adapters</code> 与 <code>ui-*</code></strong>。<code>core</code> 一旦出现 <code>window</code>、<a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Window/localStorage" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>localStorage</code></a> 或 <code>element-plus</code>，这套代码就无法安全跑在另一端。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>  core/              # 纯 TS：定价、优惠、订单状态机、金额</span></span>
<span class="line"><span>  services/          # 能力契约：storage/share/payment/http</span></span>
<span class="line"><span>  adapters/pc|h5/    # 端能力实现，允许碰平台 API</span></span>
<span class="line"><span>  composables/       # 共享 Vue 逻辑，只依赖 core + services</span></span>
<span class="line"><span>  ui-shared/         # 无交互范式组件：价格、评分、空态</span></span>
<span class="line"><span>  ui-pc/  ui-h5/     # Element Plus / Vant 页面与组件</span></span>
<span class="line"><span>  router/ stores/    # 业务 name 路由表、Pinia 领域 store</span></span>
<span class="line"><span>  entries/pc.ts      # 唯一组装点：注入 adapter、注册 UI 库</span></span>
<span class="line"><span>  entries/h5.ts</span></span></code></pre></div><p>物理隔离而不能只靠 Code Review：一次 <code>import { ElMessage } from &#39;element-plus&#39;</code> 就会把整个组件库拖进 H5 产物。<code>119-01</code> 把纪律做成生成器：模块声明层级与依赖，生成前校验越层依赖、跨端引用、UI 库串端、依赖环与命名，任一违规直接抛错。</p><blockquote><p>运行方式：<code>npx tsx examples/119-01-project-scaffold.ts</code></p></blockquote><p>生成器还会输出拓扑序、目录清单与双端入口，并把 <code>ui-pc</code> 模块的 target 锁成 <code>[&#39;pc&#39;]</code>，保证 PC 组件不会进入 H5 产物——比构建后再看体积更早、更便宜。</p><h3 id="应用实践-1" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-1" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li><code>entries</code> 是唯一组装点：PC 注入 PC adapter 与路由，H5 注入 H5 版本，业务代码不判断端。</li><li>新模块先声明 layer 与 deps 再写代码，生成器报错比线上串端便宜两个数量级。</li></ul><h3 id="最佳实践-1" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-1" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ ESLint 同时禁止 <code>core → adapters</code>、<code>ui-pc ↔ ui-h5</code> 与跨端 UI 库导入。</li></ul><hr><h2 id="_119-3-数据层-api、状态与缓存" tabindex="-1">119.3 数据层：API、状态与缓存 <a class="header-anchor" href="#_119-3-数据层-api、状态与缓存" aria-label="Permalink to &quot;119.3 数据层：API、状态与缓存&quot;">​</a></h2><h3 id="概念解析-2" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-2" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>数据层分四段，每段只做一件事：</p><table tabindex="0"><thead><tr><th>层</th><th>职责</th><th>不该做的事</th></tr></thead><tbody><tr><td>API client</td><td>URL、超时、取消、重试、traceId</td><td>不懂业务字段</td></tr><tr><td>Repository</td><td>DTO → 领域模型、错误归一、缓存</td><td>不碰 UI 状态</td></tr><tr><td>Store（Pinia）</td><td>领域状态、动作编排、跨页共享</td><td>不直接发裸请求</td></tr><tr><td>View</td><td>渲染与交互</td><td>不吞错误、不猜字段</td></tr></tbody></table><p>三个高频事故：<strong>金额用浮点</strong>（舍入直接造成资损，必须用最小单位整数）；<strong>错误只分成功/失败</strong>（UI 无法判断该重试、刷新还是重新登录）；<strong>取消当失败</strong>（切页 abort 进入错误上报会淹没监控）。</p><p><code>119-02</code> 把三件事做实：DTO 映射、错误归一、带退避与取消穿透的 <code>requestWithRetry</code>，以及 TTL/单飞/标签失效/陈旧兜底的缓存。</p><blockquote><p>运行方式：<code>npx tsx examples/119-02-domain-api-layer.ts</code></p></blockquote><p>缓存按资源的新鲜度价值定，不能一把梭 <code>Cache-First</code>：</p><table tabindex="0"><thead><tr><th>资源</th><th>策略</th><th>TTL</th><th>失效</th></tr></thead><tbody><tr><td>商品详情</td><td>内存 TTL + 陈旧兜底</td><td>5 分钟</td><td>价格/库存变更按 <code>product</code> 标签</td></tr><tr><td>首页 feed</td><td>短 TTL + 单飞</td><td>60 秒</td><td>运营发布后按 <code>feed</code> 标签</td></tr><tr><td>用户资料</td><td>内存 TTL</td><td>10 分钟</td><td>修改成功后主动失效</td></tr><tr><td>订单 / 支付结果</td><td><strong>不缓存</strong></td><td>—</td><td>每次回源，避免展示过期状态</td></tr></tbody></table><h3 id="应用实践-2" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-2" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>列表页并发请求同一详情时，单飞把 N 次网关调用压成 1 次，这是弱网下最便宜的优化。</li><li>重试只覆盖网络错误、429、5xx；401 先刷新 token 且只重试一次，409 交给用户刷新。</li></ul><h3 id="最佳实践-2" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-2" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 所有写操作带幂等键，重试与连点都不会产生重复订单。</li><li>✅ 错误归一保留 <code>requestId</code>，客服能直接对到网关日志。</li></ul><hr><h2 id="_119-4-核心业务模块" tabindex="-1">119.4 核心业务模块 <a class="header-anchor" href="#_119-4-核心业务模块" aria-label="Permalink to &quot;119.4 核心业务模块&quot;">​</a></h2><h3 id="概念解析-3" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-3" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>五个核心模块的共性不是「页面多」，而是<strong>失败路径比成功路径多</strong>。先列状态与失败路径，再写页面：</p><table tabindex="0"><thead><tr><th>模块</th><th>前端职责</th><th>关键状态 / 失败路径</th><th>双端差异</th></tr></thead><tbody><tr><td>登录</td><td>token 存取、刷新单飞、登出清理</td><td><code>anonymous → authenticating → authenticated → refreshing</code>；401 刷新失败即登出</td><td>PC 设备管理、改密；H5 第三方登录</td></tr><tr><td>列表</td><td>游标分页、去重、空态/错误态</td><td><code>idle → loading → ready → empty → error</code>；重复 key 按 id 去重</td><td>PC 表格列设置；H5 无限滚动</td></tr><tr><td>详情</td><td>预取、骨架屏、深链参数</td><td>404 / 下架 / 区域不可售是三种不同页面</td><td>PC 多图放大；H5 轮播 + 分享</td></tr><tr><td>支付</td><td>发起、回跳、轮询、恢复</td><td><code>created → redirecting → pending → paid / failed / refunded</code>；只允许前进</td><td>PC 3DS 跳转；H5 钱包 / Apple Pay</td></tr><tr><td>IM 入口</td><td>懒连接、未读聚合、重连</td><td><code>idle → connecting → open → reconnecting → closed</code></td><td>PC 独立窗口；H5 半屏 + 轮询兜底</td></tr></tbody></table><p>两条硬规则：<strong>支付状态只信服务端</strong>（回跳参数只作为「去查询」的信号，未知显示「确认中」）；<strong>IM 入口不要首屏连接</strong>（未读数走轻量轮询，时序见<a href="./116-im-weak-network">第一百一十六部分</a>）。</p><h3 id="应用实践-3" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-3" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>登录刷新用单飞：多个 401 同时到达只发一次 refresh，其余请求排队等结果。</li><li>列表记录游标而非页码；支付回跳先「确认中」，轮询未知则提供「查看订单」。</li></ul><h3 id="最佳实践-3" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-3" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 每个模块先画状态机再写组件，非法迁移在领域层拒绝。</li></ul><hr><h2 id="_119-5-双端差异与降级" tabindex="-1">119.5 双端差异与降级 <a class="header-anchor" href="#_119-5-双端差异与降级" aria-label="Permalink to &quot;119.5 双端差异与降级&quot;">​</a></h2><h3 id="概念解析-4" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-4" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>端判断的正确顺序：<strong>构建期确定端 → 运行期探测能力 → 能力缺失走降级</strong>。不要用 UA 猜端：UA 可伪造、会被精简，触摸本与横屏平板都会误判。运行期只探测具体能力（<code>navigator.share</code>、<code>pointer: coarse</code>、存储配额）。</p><table tabindex="0"><thead><tr><th>能力</th><th>PC</th><th>H5</th><th>缺失时的降级</th></tr></thead><tbody><tr><td>分享</td><td>Web Share / 复制链接</td><td><code>navigator.share</code>，不支持则复制</td><td>隐藏原生分享，保留复制</td></tr><tr><td>支付</td><td>3DS 跳转 / 卡支付</td><td>Apple Pay / Google Pay / 钱包 deep link</td><td>钱包不可用回退卡支付</td></tr><tr><td>存储</td><td>IndexedDB</td><td>localStorage（配额小）</td><td>只存 token 与草稿，图片不落库</td></tr><tr><td>上传</td><td>大文件分片</td><td>压缩后单请求</td><td>超限提示，不静默失败</td></tr><tr><td>IM</td><td>WebSocket 独立窗口</td><td>WS + 轮询兜底</td><td>后台暂停连接，回前台补拉</td></tr></tbody></table><p>路由降级是硬职责：PC 专属路由（批量导入、发票管理）在 H5 打开应跳首页并提示，而不是 404；旧链接跨端打开按业务 <code>name</code> 重建路径，参数不能丢，详见<a href="./114-vue-router-deep">第一百一十四部分</a>。</p><p>反例（双端逻辑漂移）：PC 的优惠计算写在 <code>CheckoutPc.vue</code> 的 computed 里，H5 又抄一份并「顺手」改成满减可叠加。三个月后两人分别改需求，同一订单两端算出不同价格。根因不是谁写错，而是业务规则没有唯一归属——它必须住在 <code>core/pricing</code>。</p><h3 id="应用实践-4" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-4" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>能力探测结果集中成 <code>profile</code> 对象，在 <code>entries</code> 启动时注入，页面只读不猜。</li></ul><h3 id="最佳实践-4" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-4" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 同一业务规则只允许一个实现，双端差异只体现在调用方式与展示。</li><li>⚠️ 不要用媒体查询替代业务降级：屏幕窄不代表能力缺失。</li></ul><hr><h2 id="_119-6-质量-测试、监控与灰度" tabindex="-1">119.6 质量：测试、监控与灰度 <a class="header-anchor" href="#_119-6-质量-测试、监控与灰度" aria-label="Permalink to &quot;119.6 质量：测试、监控与灰度&quot;">​</a></h2><h3 id="概念解析-5" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-5" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>质量不是「测得多」，而是<strong>在正确的层级测正确的东西</strong>：</p><table tabindex="0"><thead><tr><th>层级</th><th>测什么</th><th>频率</th><th>失败含义</th></tr></thead><tbody><tr><td>单元</td><td><code>core</code> 定价、优惠、状态机、金额</td><td>每次提交</td><td>业务规则坏了</td></tr><tr><td>契约</td><td>两端 adapter 同构、路由 name 齐全</td><td>每次提交</td><td>端能力接口漂移</td></tr><tr><td>组件</td><td><code>ui-pc</code> / <code>ui-h5</code> 各自渲染与交互</td><td>每次提交</td><td>单端 UI 回归</td></tr><tr><td>构建</td><td>双端产物、入口、PWA、体积门禁</td><td>每次 PR</td><td>串端或预算超标</td></tr><tr><td>E2E</td><td>登录 → 商品 → 购物车 → 支付回跳</td><td>合并前 + 夜间</td><td>主链路不可用</td></tr></tbody></table><p>监控只盯三类信号：<strong>业务</strong>（下单/支付成功率）、<strong>性能</strong>（LCP/INP P75、JS 错误率）、<strong>依赖</strong>（支付网关、IM、CDN）。每类都要有 SLI、阈值与端/区域维度。</p><p>灰度是风险控制，不是发布仪式，批次与止损线提前定：</p><table tabindex="0"><thead><tr><th>批次</th><th>比例</th><th>观察窗口</th><th>止损条件</th></tr></thead><tbody><tr><td>内部</td><td>白名单</td><td>1 小时</td><td>任一 P0 报错</td></tr><tr><td>小流量</td><td>1%</td><td>2 小时</td><td>支付成功率跌 1pp 或 JS 错误率 &gt; 0.5%</td></tr><tr><td>扩量</td><td>10% → 50%</td><td>每档 4 小时</td><td>LCP P75 恶化 20%</td></tr><tr><td>全量</td><td>100%</td><td>24 小时值守</td><td>5 分钟内可决策回滚</td></tr></tbody></table><h3 id="应用实践-5" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-5" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>埋点用「业务名 + 模块名 + 端 + 区域」，不用 URL path，改路由不打断历史数据。</li><li>灰度按用户 ID 哈希分桶，同一用户始终落在同一桶，避免体验闪烁。</li></ul><h3 id="最佳实践-5" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-5" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 契约测试复用同一组断言跑两个 adapter，新增能力时两端同时红。</li></ul><hr><h2 id="_119-7-上线与运维" tabindex="-1">119.7 上线与运维 <a class="header-anchor" href="#_119-7-上线与运维" aria-label="Permalink to &quot;119.7 上线与运维&quot;">​</a></h2><h3 id="概念解析-6" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-6" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>上线的本质是<strong>把不可逆操作变成可逆操作</strong>，三道闸门必须在发布前过：</p><table tabindex="0"><thead><tr><th>闸门</th><th>必检内容</th><th>阻断条件</th></tr></thead><tbody><tr><td>发布清单</td><td>构建、单测、E2E、体积、兼容矩阵、埋点</td><td>缺项或 <code>unknown</code></td></tr><tr><td>回滚</td><td>版本、CDN、SW、后端开关、数据迁移</td><td>未演练或迁移不可逆</td></tr><tr><td>值守</td><td>发布窗口、值班人、决策权</td><td>无人能在 5 分钟内决策</td></tr></tbody></table><p>反例（上线无回滚）：某团队周五晚全量发布新版结账页，未灰度、未准备回滚。20 分钟后支付成功率从 97% 掉到 61%，新版把 3DS 回跳参数解析错了；CDN 与后端同时变更，回滚花了 40 分钟，损失一个周末的投放预算。问题不在写错一行代码，而在没有任何止损路径。</p><p><code>119-03</code> 把门禁做成可执行判定：必检项缺失、状态非 <code>pass</code>、体积超预算、分类无必检项全部阻断；可选检查失败只进告警。判定逻辑把「缺项」归一成 <code>missing:&lt;id&gt;</code>，把失败归一成 <code>check:&lt;id&gt;</code>，输出可直接贴进发布单。</p><blockquote><p>运行方式：<code>npx tsx examples/119-03-release-checklist.ts</code></p></blockquote><h3 id="应用实践-6" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-6" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>清单由 CI 生成，人工只补兼容矩阵与回滚演练这类机器判断不了的项。</li><li>回滚方案写清楚：切回哪个版本、CDN 怎么刷、SW 怎么降级、后端开关怎么关。</li></ul><h3 id="最佳实践-6" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-6" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 每次发布都做回滚演练，哪怕只是预发环境。</li></ul><hr><h2 id="_119-8-作品集叙事与指标" tabindex="-1">119.8 作品集叙事与指标 <a class="header-anchor" href="#_119-8-作品集叙事与指标" aria-label="Permalink to &quot;119.8 作品集叙事与指标&quot;">​</a></h2><h3 id="概念解析-7" tabindex="-1">概念解析 <a class="header-anchor" href="#概念解析-7" aria-label="Permalink to &quot;概念解析&quot;">​</a></h3><p>作品集最容易犯的错是「功能罗列」。面试官关心<strong>你如何决策、结果如何被度量</strong>。可复述的叙事是：背景与约束（海外 DTC 双端商城、投放占 60%）→ 关键决策（内核共享/UI 分端、支付只信服务端、哈希灰度）→ 结果（H5 LCP P75 4.1s→2.3s、支付成功率 94%→98.6%）→ 复盘（哪条决策被推翻、代价是什么）。</p><p>指标必须口径一致，否则数字不可比：</p><table tabindex="0"><thead><tr><th>指标</th><th>正确口径</th><th>常见错误</th></tr></thead><tbody><tr><td>转化漏斗</td><td>逐级取交集，只有走完上一步才算进入下一步</td><td>各步独立去重，跳步支付被算进转化</td></tr><tr><td>留存</td><td>注册当天入组（cohort），第 N 天有任意活跃即留存</td><td>分母混入非同期用户，留存被稀释</td></tr><tr><td>性能</td><td>P75、nearest-rank、分端分路由</td><td>用平均值掩盖长尾，样本不分端</td></tr><tr><td>异常</td><td>最小样本量 + 相对跌幅阈值</td><td>凌晨小样本波动触发告警</td></tr></tbody></table><p><code>119-04</code> 把漏斗、留存、性能 P75、阈值告警与环比异常检测算成可断言结果；漏斗逐级取交集，异常先过最小样本量再看相对跌幅。</p><blockquote><p>运行方式：<code>npx tsx examples/119-04-metrics-dashboard.ts</code></p></blockquote><h3 id="应用实践-7" tabindex="-1">应用实践 <a class="header-anchor" href="#应用实践-7" aria-label="Permalink to &quot;应用实践&quot;">​</a></h3><ul><li>作品集只放 2~3 个能讲清决策的项目，每个配架构图、指标曲线与复盘。</li></ul><h3 id="最佳实践-7" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践-7" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>✅ 数字必须能追溯到埋点或监控，不能凭印象。</li></ul><hr><h2 id="_119-9-自测题" tabindex="-1">119.9 自测题 <a class="header-anchor" href="#_119-9-自测题" aria-label="Permalink to &quot;119.9 自测题&quot;">​</a></h2><blockquote><p>先自己作答，再展开参考答案。</p></blockquote><details><summary><b>1. 双端项目为什么不能按「功能对等」拆需求？范围矩阵至少要有什么列？【基础】</b></summary><p>同一业务目标在两种场景下价值不同：PC 适合深度操作，H5 承接投放与即时决策。功能对等会把 PC 重组件带进 H5，拖慢首屏。矩阵至少要有模块、端、优先级、验收口径、依赖；没有验收口径不算拆完。</p></details><details><summary><b>2. 目录为什么按依赖方向切？\`core\` 引入 Vue 会怎样？【基础】</b></summary><p>页面会重组，依赖方向稳定。按层切能把业务规则锁在 <code>core</code>、端差异锁在 <code>adapters</code> 与 <code>ui-*</code>。<code>core</code> 一旦引入 Vue/Pinia/DOM API，就无法在另一端复用，最终业务规则会被复制成两份。</p></details><details><summary><b>3. DTO 为什么要映射成领域模型？金额为什么用最小单位整数？【基础】</b></summary><p>DTO 是接口形状，字段与状态会随后端变化；领域模型是页面稳定依赖的契约，映射层负责校验、补默认值与派生字段。浮点金额存在舍入误差，会造成资损；最小单位整数运算精确，展示时再按币种精度格式化。</p></details><details><summary><b>4. 哪些错误可自动重试？为什么取消不能当错误？【进阶】</b></summary><p>可重试：网络错误、超时、429、5xx。不可重试：400/422、401/403、404、409 与业务拒绝；401 可先刷新 token 且只重试一次。取消是用户意图，不是服务异常；若当失败会触发无意义重试、污染错误率与告警。</p></details><details><summary><b>5. TTL、单飞、标签失效、陈旧兜底各自解决什么？【进阶】</b></summary><p>TTL 控制新鲜度；单飞让同一 key 的并发请求共享 Promise，避免列表页重复打网关；标签失效在数据变更后批量清缓存；陈旧兜底在回源失败且未超窗口时返回旧值，弱网不白屏。订单与支付结果永不缓存。</p></details><details><summary><b>6. 端判断为什么不能只看 UA？正确顺序是什么？【进阶】</b></summary><p>UA 可伪造、会被精简，触摸笔记本与横屏平板都会误判。正确顺序：构建期由 mode 确定端 → 运行期探测具体能力（<code>navigator.share</code>、<code>pointer: coarse</code>、存储配额）→ 缺失按降级矩阵回退。屏幕宽度只影响布局，不决定业务能力。</p></details><details><summary><b>7. 发布门禁为什么「缺项」也要阻断？\`unknown\` 怎么算？【挑战】</b></summary><p>缺项意味着没有证据证明通过，风险与失败等价；<code>unknown</code>（如兼容矩阵未确认）同理，不能按「差不多可以发」放行。缺项、非 <code>pass</code>、超预算、分类无必检项都应阻断；可选检查失败只进告警，避免门禁被无关项拖死。</p></details><details><summary><b>8. 漏斗、留存与异常检测的口径陷阱分别是什么？【挑战】</b></summary><p>漏斗必须逐级取交集，否则跳步支付会虚高转化；留存分母只能是注册当天入组的 cohort，不能混入非同期用户；异常检测先过最小样本量再看相对跌幅，否则凌晨小样本波动会持续误报，绝对跌幅也无法跨指标比较。</p></details><hr><h2 id="_119-10-本章避坑清单" tabindex="-1">119.10 本章避坑清单 <a class="header-anchor" href="#_119-10-本章避坑清单" aria-label="Permalink to &quot;119.10 本章避坑清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>坑点</th><th>现象</th><th>根因</th><th>正确姿势</th></tr></thead><tbody><tr><td>1</td><td>按「功能对等」拆双端需求</td><td>H5 首屏被 PC 组件拖慢</td><td>把端差异当复制粘贴</td><td>范围矩阵 + 验收口径 + 范围冻结</td></tr><tr><td>2</td><td>业务规则写在页面里</td><td>两端算价/优惠不一致</td><td>规则没有唯一归属</td><td>规则只住 <code>core</code>，两端只调用</td></tr><tr><td>3</td><td>金额用浮点</td><td>差一分钱、对账失败</td><td>浮点误差、精度写死 2 位</td><td>最小单位整数 + 按币种格式化</td></tr><tr><td>4</td><td>错误只分成功/失败</td><td>所有错误都弹「稍后重试」</td><td>没有错误分类</td><td>归一 <code>kind</code> + <code>retryable</code> + <code>requestId</code></td></tr><tr><td>5</td><td>取消当失败上报</td><td>错误率虚高、告警噪声</td><td>abort 未独立建模</td><td>独立错误类型，不重试不上报</td></tr><tr><td>6</td><td>所有请求都自动重试</td><td>重复下单、重复扣款</td><td>POST 无幂等却重试</td><td>写操作带幂等键，支付只查不重试</td></tr><tr><td>7</td><td>支付回跳即置为已支付</td><td>未扣款也显示成功</td><td>信了前端回跳参数</td><td>只信服务端查询，未知显示「确认中」</td></tr><tr><td>8</td><td>用 UA 判断端</td><td>平板/触摸本体验错乱</td><td>UA 可伪造且被精简</td><td>构建期定端 + 运行期能力探测</td></tr><tr><td>9</td><td>PC 专属路由在 H5 直接 404</td><td>用户丢失、客服工单增加</td><td>路由表没有降级职责</td><td>跳首页并提示，参数保留</td></tr><tr><td>10</td><td>上线无回滚、无灰度</td><td>故障持续数十分钟到数小时</td><td>把发布当一次性动作</td><td>检查清单 + 分批灰度 + 回滚演练</td></tr></tbody></table><blockquote><p>心法：<strong>双端项目的复杂度不在「写两套 UI」，而在「让业务规则只有一份、让失败可恢复、让结果可度量」</strong>。需求守住范围、架构守住依赖方向、数据守住金额与错误、上线守住回滚与灰度——这四道闸门守住了，项目才从「能跑」变成「敢上线」。</p></blockquote>`,114)])])}const b=d(o,[["render",l]]);export{u as __pageData,b as default};
